Je tohle legit řešení?
```C
int main(argc, argv) {
  MPI_Init(argc, argv);
  int rank, size, value;
  int sum, average, a_sum;
  MPI_Reduce(&value, &sum, MPI_Sum, 0);
  if (rank == 0) average = sum/size;
  MPI_Bcast(&average, 0);
  if (value < average) value = 0;
  MPI_Reduce(&value, &a_sum, MPI_Sum, 0);
  if (rank == 0) std::cout << "Suma: " << a_sum << std::endl;
}
```

